mapper.insert:
/*AdminUserHomeMng_SQL.adminMenuReg*/
INSERT INTO TB_ADMIN_MENU_INFO (
	  MENU_ID
	, MENU_P_ID
	, MENU_NM
	, MENU_URL
	, MENU_USE_YN
	, MENU_DEL_YN
	, MENU_CN
	, MENU_LVL
	, MENU_SORT
	, MENU_DEPT_CD
	, MENU_TEAM_CD
	, MENU_POSITION_CD
	, MENU_ICON
	, MENU_GRADE_CD
	, MENU_PAGE_GB
	, REG_ID
	, REG_DT
	, UPD_ID
	, UPD_DT
) VALUES ( 
	  (SELECT FN_GET_UNIQUE_KEY())
	, #{menuPId}
	, #{menuNm}
	, #{menuUrl}
	, #{menuUseYn}
	, 'N'
	, #{menuCn}
	, #{menuLvl}
	, #{menuSort}
	, #{menuDeptCd}
	, #{menuTeamCd}
	, #{menuPositionCd}
	, #{menuIcon}
	, #{menuGradeCd}
	, #{menuPageGb}
	, #{regId}
	, NOW()
	, #{updId}
	, NOW()
)

mapper.update:
  		/*AdminUserHomeMng_SQL.adminMenuDel*/
	  	UPDATE TB_ADMIN_MENU_INFO
	     	 SET MENU_NM 				= #{menuNm}
				 , MENU_URL				= #{menuUrl}
				 , MENU_USE_YN			= #{menuUseYn}
				 , MENU_CN					= #{menuCn}
				 , MENU_LVL				= #{menuLvl}
				 , MENU_SORT				= #{menuSort}
				 , MENU_DEPT_CD		= #{menuDeptCd}
				 , MENU_TEAM_CD		= #{menuTeamCd}
				 , MENU_POSITION_CD	= #{menuPositionCd}
				 , MENU_ICON				= #{menuIcon}
				 , MENU_GRADE_CD		= #{menuGradeCd} 
				 , UPD_ID					= #{updId}
				 , UPD_DT					= NOW()
	   WHERE 1=1 
	   	   AND MENU_ID = #{menuId}

  		/*AdminUserHomeMng_SQL.adminMenuDel*/
	  	UPDATE TB_ADMIN_MENU_INFO
	     	 SET MENU_DEL_YN = 'Y'
	     	   	  , UPD_ID = #{updId}
	     	 	  , UPD_DT = NOW()
	    WHERE 1=1 
	   	    AND MENU_ID   = #{menuId} 
 	   	 
	   	 	  OR MENU_P_ID = #{menuId}
